import { renderMazeFieldAssists } from './companion-field-assists-ui.js';
import { renderActiveExpeditionAccount } from './maze-receipt-ui.js';
import { mazeExpeditionView } from './maze-expedition.js';
import { mazeMovementDescription } from './maze-rules.js';
import { mazeLayout, mazeRoomText, mazeRoomCell } from './maze-v31.js';
import { getActions } from './engine.js';
import { renderAreaScene } from './area-scenes.js';
import { compactActivityRows } from './activities-v31.js';
import { mazeMapView, renderMazeMapTools, MAZE_MARK_LABELS, MAZE_MARK_SYMBOLS } from './maze-map-ui.js';
const reserve=(current,max)=>Number.isFinite(current)&&Number.isFinite(max)?`${current}/${max}`:'unavailable';
export function renderMazeExpedition(s,ui,actions){
 const v=mazeExpeditionView(s,actions);if(!v)return '';const {e}=ui,m=v.movement;
 return `<section class="maze-expedition" aria-labelledby="maze-expedition-title"><h3 id="maze-expedition-title">Expedition resources</h3><p id="maze-movement-cost"><strong>Next walk:</strong> ${e(mazeMovementDescription(m))}</p><p class="small-copy">Next movement day in ${m.stepsUntilDay} walk${m.stepsUntilDay===1?'':'s'} (total step ${m.dayOnStep}), assuming no other Focus changes. Calendar needs may pause a walk; only completed movement spends Focus.</p><p class="small-copy">${v.kitNights} kit night${v.kitNights===1?'':'s'} carried${v.kit?` · next pack: ${e(v.kit.name)} (${v.kit.remaining})`:''} · ${v.potions} potion${v.potions===1?'':'s'} · ${v.rations} ration${v.rations===1?'':'s'}.</p><details data-disclosure="maze-expedition-reserves"><summary>Active party reserves &amp; camp rules</summary><ul class="maze-reserves">${v.party.map(p=>`<li><strong>${e(p.name)}</strong><span>Health ${e(reserve(p.hp,p.maxHp))} · Focus ${e(reserve(p.mp,p.maxMp))}${p.unavailable?' · '+e(p.unavailable):''}</span></li>`).join('')}</ul><p class="small-copy">${v.campAvailable?'Camp is available in this room.':'Camp is not available now; find a safe room and resolve any waiting moment.'} ${e(v.campDescription)}</p><p class="small-copy">Walking does not use rations or kit nights. The day charge is every sixth total step, or every third when Focus is already empty before that step. Ordinary living costs apply to attended days; other actions can also take time.</p></details><p class="small-copy"><strong>Stair exit:</strong> ${v.exitAvailable?'Available here.':'Not available here.'} Use the entrance stair, or the objective’s return stair after completing its task. Retreat from combat only returns to the previous room.</p>${renderActiveExpeditionAccount(s,ui)}</section>`;
}
export function renderMaze(s,ui,session=null){
 const m=s.maze;if(!m)return '';const {e,button}=ui,l=mazeLayout(m),room=mazeRoomCell(m),text=mazeRoomText(m,s),actions=getActions(s),moves=actions.filter(a=>a.id.startsWith('maze_step_')),offers=actions.filter(a=>!a.id.startsWith('maze_step_')&&!a.id.startsWith('maze_assist_')),map=mazeMapView(s,actions,session),inspect=map?.session.mode==='inspect',route=new Set(map?.route?.path||[]);
 const symbols={entrance:'↟',empty:'·',cache:'◇',enemy:'×',guardian:'⚔',trap:'!',camp:'△',inscription:'≡',objective:'✦',witness:'○',dilemma:'≡'};
 const tiles=l.cells.map(base=>{
  const visited=m.visited.includes(base.id),near=room.doors.includes(base.id),visible=visited||near,current=base.id===m.position;
  // A known doorway does not reveal that unknown room's other walls or content.
  const c=visited?mazeRoomCell(m,base.id):base,a=moves.find(a=>a.id==='maze_step_'+base.id),entry=visited?map?.entries.find(row=>row.roomId===base.id):null;
  const walls=visited?['north','east','south','west'].map((dir,i)=>{const [dx,dy]=[[0,-1],[1,0],[0,1],[-1,0]][i],to=(c.y+dy)*l.size+c.x+dx;return !c.doors.includes(to)?'wall-'+dir:'';}).join(' '):'';
  const label=(current?'Current location':visited?'Recorded '+c.kind+' room':near?'Unknown adjoining room':'Unexplored')+(entry?.mark?' · '+MAZE_MARK_LABELS[entry.mark]+' mark':'')+(entry?.note?' · Note: '+entry.note:'');
  const command=inspect?(visited?`data-op="maze-map-select" data-id="${base.id}" tabindex="${map.session.selected===base.id?'0':'-1'}" aria-pressed="${map.session.selected===base.id}"`:'disabled'):(a?`data-op="activity" data-id="${a.id}" ${a.disabledReason?'disabled':''}`:'disabled');
  return `<button type="button" class="maze-cell ${visible?'known':'fog'} ${current?'current':''} ${visited&&m.cleared.includes(base.id)?'cleared':''} ${walls} ${visited&&route.has(base.id)?'route-room':''} ${inspect&&map.session.selected===base.id?'inspected':''}" ${command} aria-label="${e(label)}${!inspect&&a?.disabledReason?' · '+e(a.disabledReason):''}" ${current?'aria-current="location"':''}>${current?'†':visited?symbols[c.kind]:near?'?':''}${entry?`<span class="maze-mark" aria-hidden="true">${entry.mark?MAZE_MARK_SYMBOLS[entry.mark]:'✎'}</span>`:''}${visited&&route.has(base.id)?'<span class="maze-route-dot" aria-hidden="true">•</span>':''}</button>`;
 }).join('');
 return `<div class="maze-workspace"><header class="maze-heading"><div><span class="eyebrow">BENEATH ${e(s.world.locations.find(p=>p.id===s.locationId)?.name||'THE SURFACE')}</span><h1>${e(m.title)}</h1></div><span>Health ${s.hero.hp}/${s.hero.maxHp} · Focus ${s.hero.mp}/${s.hero.maxMp}</span></header>${s.event?ui.encounter():''}<div class="maze-layout"><section class="maze-chart"><div class="maze-grid" style="--maze-size:${l.size}" tabindex="0" role="group" aria-label="Dungeon Maze" data-maze-mode="${inspect?'inspect':'walk'}" aria-describedby="maze-controls maze-movement-cost">${tiles}</div><p id="maze-controls" class="small-copy">${inspect?'Inspect mode: select recorded rooms without moving. Switch to Walk to use doorways.':'Click an adjoining room to walk. Focus the map and use arrow keys, or use the direction buttons below. Walls block movement. ? is an unexplored door.'}</p>${!inspect?`<div class="maze-direction-controls" role="group" aria-label="Walk through a doorway" aria-describedby="maze-movement-cost">${moves.map(a=>button(a.label,'activity',a.id,'secondary small',Boolean(a.disabledReason))).join('')}</div>`:''}<p class="small-copy">${m.visited.length}/${l.cells.length} rooms recorded · ↟ Entrance · △ Shelter · ◇ Cache · ✦ Objective</p>${renderMazeMapTools(s,map,ui)}</section><section class="maze-current"><h2 tabindex="-1">${e(text.title)}</h2>${renderAreaScene(s,ui,{dungeon:{room:text}})}<p>${e(text.body)}</p>${m.objective?'<p class="badge">Objective Complete</p>':''}${renderMazeExpedition(s,ui,actions)}${renderMazeFieldAssists(s,actions,ui)}${compactActivityRows(offers,ui)}${!offers.length?'<p class="small-copy">The doors on the map lead onward.</p>':''}${button('Inventory','tab','inventory','ghost small')}</section></div></div>`;
}
